changeSet.sql:
CREATE TABLE notifications ( id UUID PRIMARY KEY, recipient_user_id UUID NOT NULL, recipient_email VARCHAR(255) NULL, recipient_phone VARCHAR(60) NULL, channel VARCHAR(20) NOT NULL, template_code VARCHAR(120) NOT NULL, subject VARCHAR(255) NULL, message TEXT NOT NULL, status VARCHAR(40) NOT NULL, retry_count INT NOT NULL, max_retries INT NOT NULL DEFAULT 3, related_entity_type VARCHAR(80) NULL, related_entity_id UUID NULL, insurance_company_id UUID NULL, hospital_id UUID NULL, created_at TIMESTAMP NOT NULL, sent_at TIMESTAMP NULL, updated_at TIMESTAMP NOT NULL, error_message TEXT NULL );
CREATE TABLE notification_templates ( id UUID PRIMARY KEY, template_code VARCHAR(120) NOT NULL, channel VARCHAR(20) NOT NULL, subject_template VARCHAR(255) NULL, body_template TEXT NOT NULL, status VARCHAR(20) NOT NULL, created_at TIMESTAMP NOT NULL, CONSTRAINT uk_notification_template_code_channel UNIQUE(template_code, channel) );
CREATE TABLE notification_retries ( id UUID PRIMARY KEY, notification_id UUID NOT NULL REFERENCES notifications(id), attempt_number INT NOT NULL, failure_reason TEXT NOT NULL, attempted_at TIMESTAMP NOT NULL );
CREATE INDEX idx_notifications_recipient_user ON notifications(recipient_user_id); CREATE INDEX idx_notifications_company ON notifications(insurance_company_id); CREATE INDEX idx_notifications_hospital ON notifications(hospital_id); CREATE INDEX idx_notifications_status_retry ON notifications(status, retry_count); CREATE INDEX idx_notifications_related ON notifications(related_entity_type, related_entity_id); CREATE INDEX idx_notification_retries_notification ON notification_retries(notification_id);
